import{_ as a,o as e,c as r,a2 as i}from"./chunks/framework.ktMMbWgA.js";const v=JSON.parse('{"title":"第 1 讲 · 你以为你在思考 — 当大脑遇上统计学 · 参考","description":"","frontmatter":{"title":"第 1 讲 · 你以为你在思考 — 当大脑遇上统计学 · 参考","act":1,"kind":"refs","prev":{"text":"L00 · 序章 · 从 50 行代码开始","link":"/lectures/L00-prologue/references"},"next":{"text":"L02 · 经典 AI 的兴衰","link":"/lectures/L02-classical-ai/references"}},"headers":[],"relativePath":"lectures/L01-cognitive-biases/references.md","filePath":"lectures/L01-cognitive-biases/references.md","lastUpdated":null}'),t={name:"lectures/L01-cognitive-biases/references.md"};function l(n,s,d,c,o,f){return e(),r("div",null,[...s[0]||(s[0]=[i('<h1 id="l01-参考-·-references-你以为你在思考-—-当大脑遇上统计学-cognitive-biases-and-human-intelligence-as-statistical-intuition" tabindex="-1">L01 参考 · References：你以为你在思考 — 当大脑遇上统计学（Cognitive Biases and Human Intelligence as Statistical Intuition） <a class="header-anchor" href="#l01-参考-·-references-你以为你在思考-—-当大脑遇上统计学-cognitive-biases-and-human-intelligence-as-statistical-intuition" aria-label="Permalink to &quot;L01 参考 · References：你以为你在思考 — 当大脑遇上统计学（Cognitive Biases and Human Intelligence as Statistical Intuition）&quot;">​</a></h1><blockquote><p><strong>Lecture</strong>: 你以为你在思考 / &quot;You Think You&#39;re Thinking&quot; <strong>Course</strong>: Intelligence, Computed — From First Principles to Production AI Systems</p></blockquote><blockquote><p><strong>Last Verified</strong>: 2026-05-04 (links and citations checked; replace this when re-verifying)</p></blockquote><hr><section class="ref-card"><h2 class="ref-card-title" id="学术论文">1. 学术论文</h2><h3 class="ref-group" id="学术论文--奠基性的-kahneman-tversky-论文">奠基性的 Kahneman &amp; Tversky 论文</h3><ol class="ref-list"><li class="ref-item" id="ref-P1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P1</span><a class="ref-title" href="https://www.science.org/doi/abs/10.1126/science.185.4157.1124" target="_blank" rel="noopener">Judgment under Uncertainty: Heuristics and Biases</a></div><div class="ref-meta">Tversky, A. &amp; Kahneman, D. · 1974 · <em>Science</em>, 185(4157), 1124–1131</div><div class="ref-links"><a class="ref-link" href="https://apps.dtic.mil/sti/pdfs/AD0767426.pdf" target="_blank" rel="noopener">PDF</a></div><p class="ref-desc"><strong>核心参考。</strong> 定义可得性、代表性、锚定三大启发式的开山之作。Linda 问题与锚定实验都直接源自这条研究脉络。被引 58,000+。</p></div></li><li class="ref-item" id="ref-P2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P2</span><a class="ref-title" href="https://web.archive.org/web/20141117055859/http://people.hss.caltech.edu/~camerer/Ec101/ProspectTheory.pdf" target="_blank" rel="noopener">Prospect Theory: An Analysis of Decision under Risk</a></div><div class="ref-meta">Kahneman, D. &amp; Tversky, A. · 1979 · <em>Econometrica</em>, 47(2), 263–291</div><p class="ref-desc">损失厌恶的奠基。证明人类并非理性效用最大化者——对损失的权重约是收益的 2 倍。适合&quot;你的大脑是有偏的预测机器&quot;叙事。</p></div></li><li class="ref-item" id="ref-P3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P3</span><span class="ref-title">Extensional versus Intuitive Reasoning: The Conjunction Fallacy in Probability Judgment</span></div><div class="ref-meta">Tversky, A. &amp; Kahneman, D. · 1983 · <em>Psychological Review</em>, 90(4), 293–315</div><p class="ref-desc">&quot;Linda 问题&quot;原论文。最适合课堂现场演示——先让学生回答，再揭示合取谬误。</p></div></li><li class="ref-item" id="ref-P4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P4</span><a class="ref-title" href="https://www.sciencedirect.com/science/article/pii/0010028573900339" target="_blank" rel="noopener">Availability: A Heuristic for Judging Frequency and Probability</a></div><div class="ref-meta">Tversky, A. &amp; Kahneman, D. · 1973 · <em>Cognitive Psychology</em>, 5(2), 207–232</div><p class="ref-desc">解释为何人们高估戏剧化风险（恐袭、空难）、低估平凡风险（糖尿病、中风）。适合&quot;大脑走捷径&quot;片段。</p></div></li><li class="ref-item" id="ref-P5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P5</span><span class="ref-title">Belief in the Law of Small Numbers</span></div><div class="ref-meta">Tversky, A. &amp; Kahneman, D. · 1971 · <em>Psychological Bulletin</em>, 76(2), 105–110</div><p class="ref-desc">连统计学家也会被小样本欺骗。可用于把人类直觉的失败连接到机器学习中&quot;大数据为何重要&quot;。</p></div></li><li class="ref-item" id="ref-P6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P6</span><span class="ref-title">The Framing of Decisions and the Psychology of Choice</span></div><div class="ref-meta">Tversky, A. &amp; Kahneman, D. · 1981 · <em>Science</em>, 211(4481), 453–458</div><p class="ref-desc">框架效应——同样的信息以不同方式呈现就会导致相反决策。经典的&quot;手术存活率&quot;案例适合现场演示。</p></div></li><li class="ref-item" id="ref-P7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P7</span><a class="ref-title" href="https://web.archive.org/web/20180219074537/http://www.econ.tuwien.ac.at/lotto/papers/Kahneman2.pdf" target="_blank" rel="noopener">Maps of Bounded Rationality: Psychology for Behavioral Economics</a></div><div class="ref-meta">Kahneman, D. · 2003 · <em>American Economic Review</em>, 93(5), 1449–1475</div><p class="ref-desc">Kahneman 的诺贝尔讲座。对整个 System 1/System 2 框架的精彩总结，适合作为备课的单篇综述。</p></div></li></ol><h3 class="ref-group" id="学术论文--认知的计算模型与-ai-联系">认知的计算模型与 AI 联系</h3><ol class="ref-list"><li class="ref-item" id="ref-P8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P8</span><a class="ref-title" href="https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6129743" target="_blank" rel="noopener">A Neural Network Framework for Cognitive Bias</a></div><div class="ref-meta">Korteling, J.E., Brouwer, A.-M. &amp; Toet, A. · 2018 · <em>Frontiers in Psychology</em>, 9, 1561</div><p class="ref-desc"><strong>直接架起认知偏误与神经网络的桥梁。</strong> 论证认知偏误源于使神经信息处理高效的同一套机制——直接支持本讲&quot;压缩的统计直觉&quot;论点。</p></div></li><li class="ref-item" id="ref-P9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P9</span><span class="ref-title">Homo Heuristicus: Why Biased Minds Make Better Inferences</span></div><div class="ref-meta">Gigerenzer, G. &amp; Brighton, H. · 2009 · <em>Topics in Cognitive Science</em>, 1(1), 107–143</div><p class="ref-desc">反方视角：偏误不是 bug，而是生态理性的 feature。启发式常常胜过复杂模型——呼应&quot;简单 ML 模型为何有时打败复杂模型&quot;。</p></div></li><li class="ref-item" id="ref-P10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P10</span><span class="ref-title">Toward a Synthesis of Cognitive Biases: How Noisy Information Processing Can Bias Human Decision Making</span></div><div class="ref-meta">Hilbert, M. · 2012 · <em>Psychological Bulletin</em>, 138(2), 211–237</div><p class="ref-desc">&quot;统一框架：把认知偏误解释为含噪信息处理的产物。直接支持&quot;智能即统计计算&quot;的框架。</p></div></li><li class="ref-item" id="ref-P11"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P11</span><span class="ref-title">A Logical Calculus of the Ideas Immanent in Nervous Activity</span></div><div class="ref-meta">McCulloch, W.S. &amp; Pitts, W. · 1943 · <em>Bulletin of Mathematical Biophysics</em>, 5(4), 115–133</div><p class="ref-desc">开启一切的那篇论文——证明神经活动可被建模为逻辑计算。&quot;70 年&quot; AI 史叙事的关键。</p></div></li><li class="ref-item" id="ref-P12"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P12</span><a class="ref-title" href="https://global.oup.com/academic/product/simple-heuristics-that-make-us-smart-9780195143812" target="_blank" rel="noopener">Simple Heuristics That Make Us Smart</a></div><div class="ref-meta">Gigerenzer, G., Todd, P.M. &amp; ABC Research Group · 1999 · Oxford University Press</div><p class="ref-desc">&quot;少即是多&quot;——简单决策规则常胜过复杂模型。可顺势引出偏差-方差权衡，以及神经网络为何要 dropout/正则化。</p></div></li></ol><h3 class="ref-group" id="学术论文--近期论文-2024-2026-人类认知-机器学习">近期论文（2024–2026）：人类认知 × 机器学习</h3><ol class="ref-list"><li class="ref-item" id="ref-P13"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P13</span><span class="ref-title">Cognitive Biases in Fact-Checking and Their Countermeasures: A Review</span></div><div class="ref-meta">2024 · <em>Information Processing &amp; Management</em>, 61(3), 103672</div><p class="ref-desc">当代研究表明认知偏误甚至影响谨慎的事实核查者。与 AI 可信度讨论相关。</p></div></li><li class="ref-item" id="ref-P14"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P14</span><span class="ref-title">Heuristics and Cognitive Biases: A Conceptual Analysis</span></div><div class="ref-meta">Nadurak, V. · 2025 · <em>Memory &amp; Cognition</em> (advance online)</div><p class="ref-desc">最新概念综述。把 Kahneman/Tversky 与 Gigerenzer 之争更新到 2025 年。</p></div></li><li class="ref-item" id="ref-P15"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P15</span><span class="ref-title">How to Evaluate the Rationality of Heuristics?</span></div><div class="ref-meta">Nadurak, V. · 2025 · <em>Thinking &amp; Reasoning</em>, 31(2), 137–157</div><p class="ref-desc">评估&quot;何时启发式是理性、何时是偏误&quot;的新框架。</p></div></li><li class="ref-item" id="ref-P16"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P16</span><a class="ref-title" href="https://arxiv.org/abs/2303.12712" target="_blank" rel="noopener">Sparks of Artificial General Intelligence: Early Experiments with GPT-4</a></div><div class="ref-meta">Bubeck, S. et al. · 2023 · arXiv:2303.12712</div><p class="ref-desc">Microsoft Research 论文，主张 GPT-4 显示出通用智能的&quot;火花&quot;。与&quot;机器是否也有压缩的统计直觉&quot;相关。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="书籍">2. 书籍</h2><ol class="ref-list"><li class="ref-item" id="ref-B1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B1</span><span class="ref-title">Thinking, Fast and Slow</span></div><div class="ref-meta">Daniel Kahneman · 2011 · Farrar, Straus and Giroux</div><p class="ref-desc"><strong>System 1/System 2 的主文本。</strong> 第一部分（两套系统）、第二部分（启发式与偏误）直接相关。重点章节：第 1 章（两套系统）、第 3 章（懒惰的控制者）、第 4 章（联想机）、第 10–13 章（锚定、可得性、Linda）。注意：第 4 章中部分启动效应研究存在复现问题——讲课时需如实告知。</p></div></li><li class="ref-item" id="ref-B2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B2</span><span class="ref-title">Judgment Under Uncertainty: Heuristics and Biases</span></div><div class="ref-meta">Kahneman, D., Slovic, P. &amp; Tversky, A. (eds.) · 1982 · Cambridge University Press</div><p class="ref-desc"><em>Thinking, Fast and Slow</em> 的学术伴随版。更严谨，包含原始实验描述。适合用于准备课堂演示。</p></div></li><li class="ref-item" id="ref-B3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B3</span><span class="ref-title">Heuristics and Biases: The Psychology of Intuitive Judgment</span></div><div class="ref-meta">Gilovich, T., Griffin, D. &amp; Kahneman, D. (eds.) · 2002 · Cambridge University Press</div><p class="ref-desc">更新版合集，包含&quot;重访代表性&quot;——属性替换理论。</p></div></li><li class="ref-item" id="ref-B4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B4</span><span class="ref-title">The Psychology of Judgment and Decision Making</span></div><div class="ref-meta">Plous, S. · 1993 · McGraw-Hill</div><p class="ref-desc">极易上手的本科教材，覆盖所有主要偏误并附清晰实验描述。课堂演示的好素材。</p></div></li><li class="ref-item" id="ref-B5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B5</span><span class="ref-title">Irrationality</span></div><div class="ref-meta">Sutherland, S. · 2007 (2nd ed.) · Pinter &amp; Martin</div><p class="ref-desc">可读性极强的认知偏误科普。适合寻找生动案例。</p></div></li><li class="ref-item" id="ref-B6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B6</span><span class="ref-title">How We Know What Isn&#39;t So: The Fallibility of Human Reason in Everyday Life</span></div><div class="ref-meta">Gilovich, T. · 1993 · The Free Press</div><p class="ref-desc">错觉相关、聚类错觉、热手谬误——都是&quot;大脑看到不存在的规律&quot;演示的好素材。</p></div></li><li class="ref-item" id="ref-B7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B7</span><span class="ref-title">Cognitive Illusions: A Handbook on Fallacies and Biases in Thinking, Judgement and Memory</span></div><div class="ref-meta">Pohl, R.F. (ed.) · 2017 (2nd ed.) · Routledge</div><p class="ref-desc">全面的参考手册。锚定、可得性、合取谬误等各有专章并附实验协议。</p></div></li><li class="ref-item" id="ref-B8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B8</span><span class="ref-title">Machines Who Think</span></div><div class="ref-meta">McCorduck, P. · 2004 (2nd ed.) · A.K. Peters</div><p class="ref-desc">出色的 AI 叙事史，覆盖 Dartmouth 会议、符号派 vs. 连接派之争、AI 寒冬。&quot;70 年&quot;叙事的主要来源。</p></div></li><li class="ref-item" id="ref-B9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B9</span><span class="ref-title">AI: The Tumultuous Search for Artificial Intelligence</span></div><div class="ref-meta">Crevier, D. · 1993 · BasicBooks</div><p class="ref-desc">1950 至 1990 年代 AI 的详细历史。覆盖 Minsky vs. Rosenblatt、Perceptrons 之争、专家系统的兴衰。</p></div></li><li class="ref-item" id="ref-B10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B10</span><span class="ref-title"><strong>Artificial Intelligence: A Modern Approach</strong> (4th ed.)</span></div><div class="ref-meta">Russell, S.J. &amp; Norvig, P. · 2021 · Pearson</div><p class="ref-desc">第 1 章对 AI 历史与竞争范式给出极佳概览。事实标准教材。</p></div></li><li class="ref-item" id="ref-B11"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B11</span><span class="ref-title">The Society of Mind</span></div><div class="ref-meta">Minsky, M. · 1986 · Simon &amp; Schuster</div><p class="ref-desc">Minsky 关于&quot;智能由简单代理涌现&quot;的设想。与流派叙事中符号派视角相关。</p></div></li><li class="ref-item" id="ref-B12"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B12</span><span class="ref-title">Noise: A Flaw in Human Judgment</span></div><div class="ref-meta">Kahneman, D., Sibony, O. &amp; Sunstein, C. · 2021 · Little, Brown</div><p class="ref-desc">Kahneman 对 <em>Thinking, Fast and Slow</em> 的续作。讨论人类判断中的噪声，与偏误相区分。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="视频">3. 视频</h2><h3 class="ref-group" id="视频--认知偏误与-system-1-2">认知偏误与 System 1/2</h3><ol class="ref-list"><li class="ref-item" id="ref-V1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V1</span><a class="ref-title" href="https://www.youtube.com/watch?v=cebFWOlx848" target="_blank" rel="noopener">Veritasium: The Illusion of Truth</a></div><div class="ref-meta">Derek Muller · ~18 min</div><p class="ref-desc">重复如何塑造信念。制作质量极高。可剪 2 分钟片段作为开场。</p></div></li><li class="ref-item" id="ref-V2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V2</span><span class="ref-title"><strong>Veritasium: This is Why You&#39;re Wrong</strong> (Cognitive Biases)</span></div><div class="ref-meta">Derek Muller · ~12 min</div><p class="ref-desc">覆盖确认偏误、邓宁-克鲁格效应。学生参与度高。</p></div></li><li class="ref-item" id="ref-V3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V3</span><a class="ref-title" href="https://www.youtube.com/watch?v=aircAruvnKk" target="_blank" rel="noopener">3Blue1Brown: But what is a neural network?</a></div><div class="ref-meta">Grant Sanderson · ~19 min</div><p class="ref-desc">并非直接讲偏误，但有连接点：神经网络学到的也是压缩的统计表征——和人脑做的一样。可在从&quot;人类直觉&quot;过渡到&quot;机器学习&quot;时引用。</p></div></li><li class="ref-item" id="ref-V4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V4</span><a class="ref-title" href="https://www.youtube.com/watch?v=CjVQJdIrDJ0" target="_blank" rel="noopener">Daniel Kahneman: Thinking, Fast and Slow (Talks at Google)</a></div><div class="ref-meta">Talks at Google · ~60 min</div><p class="ref-desc">Kahneman 本人讲 System 1/2 并附现场演示。可剪 5 分钟片段。</p></div></li><li class="ref-item" id="ref-V5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V5</span><span class="ref-title">The Psychology of Human Misjudgment</span></div><div class="ref-meta">Charlie Munger · ~75 min</div><p class="ref-desc">巴菲特搭档梳理 25 种认知偏误并附商业案例。展示真实世界影响。</p></div></li><li class="ref-item" id="ref-V6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V6</span><span class="ref-title">Optical Illusions and How They Work</span></div><div class="ref-meta">TED-Ed / various · ~5 min</div><p class="ref-desc">用视错觉作为开场：&quot;你的视觉系统是预测机器。通常预测对，预测错时我们叫它错觉。&quot;</p></div></li><li class="ref-item" id="ref-V7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V7</span><a class="ref-title" href="https://www.youtube.com/watch?v=R13BD8qKeTg" target="_blank" rel="noopener">Veritasium: The Bayesian Trap</a></div><div class="ref-meta">Derek Muller · ~11 min</div><p class="ref-desc">对基率忽视的精彩讲解。直接呼应&quot;你的大脑不会做贝叶斯&quot;主题。</p></div></li><li class="ref-item" id="ref-V8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V8</span><a class="ref-title" href="https://www.youtube.com/watch?v=MFzDaBzBlL0" target="_blank" rel="noopener">Smarter Every Day: Backwards Brain Bicycle</a></div><div class="ref-meta">Destin Sandlin · ~8 min</div><p class="ref-desc">演示模式匹配嵌入大脑之深。取消一个简单运动模式需要数月。&quot;智能 = 压缩的模式&quot;的直观佐证。</p></div></li></ol><h3 class="ref-group" id="视频--ai-历史">AI 历史</h3><ol class="ref-list"><li class="ref-item" id="ref-V9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V9</span><span class="ref-title">The History of Artificial Intelligence</span></div><div class="ref-meta">ColdFusion · ~25 min</div><p class="ref-desc">从 Dartmouth 讲到现代。&quot;70 年&quot;叙事的良好可视化概览。</p></div></li><li class="ref-item" id="ref-V10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V10</span><span class="ref-title">Geoffrey Hinton: The Godfather of AI</span></div><div class="ref-meta">60 Minutes / CBS · ~15 min</div><p class="ref-desc">Hinton 视角：神经网络是&quot;对的&quot;路线。连接派下注得到回报的个人化叙事。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="博客与文章">4. 博客与文章</h2><ol class="ref-list"><li class="ref-item" id="ref-A1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A1</span><a class="ref-title" href="https://en.wikipedia.org/wiki/List_of_cognitive_biases" target="_blank" rel="noopener"><strong>Cognitive Bias Codex</strong> (visual map of 188 biases)</a></div><div class="ref-meta">Buster Benson / Wikipedia</div><div class="ref-links"><a class="ref-link" href="https://www.titlemax.com/discovery-center/lifestyle/50-cognitive-biases-to-be-aware-of-so-you-can-be-the-very-best-version-of-you/" target="_blank" rel="noopener">Codex poster</a></div><p class="ref-desc">把完整的偏误地图作为戏剧化展示：&quot;这就是你大脑不打招呼就在做的事。&quot;按估计、决策、假设评估、因果归因、回忆、意见报告分类。</p></div></li><li class="ref-item" id="ref-A2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A2</span><a class="ref-title" href="https://www.theguardian.com/science/2014/feb/16/daniel-kahneman-thinking-fast-and-slow-tributes" target="_blank" rel="noopener">Daniel Kahneman changed the way we think about thinking</a></div><div class="ref-meta">The Guardian (2014)</div><p class="ref-desc">致敬与访谈合集。备课的良好背景材料。</p></div></li><li class="ref-item" id="ref-A3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A3</span><span class="ref-title">&quot;Elephants Don&#39;t Play Chess&quot;</span></div><div class="ref-meta">Rodney Brooks</div><p class="ref-desc">Brooks 对符号派 AI 的正面攻击。&quot;流派&quot;叙事中具身认知视角的关键文献。</p></div></li><li class="ref-item" id="ref-A4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A4</span><a class="ref-title" href="https://people.idsia.ch/~juergen/" target="_blank" rel="noopener">Jürgen Schmidhuber: Annotated History of Modern AI and Deep Learning</a></div><div class="ref-meta">Schmidhuber, J.</div><p class="ref-desc">从连接派视角写的、详尽且有立场的 AI 编年史。&quot;70 年&quot;段落事实核查时有用。</p></div></li><li class="ref-item" id="ref-A5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A5</span><a class="ref-title" href="https://web.archive.org/web/20070926023314/http://www.aaai.org/AITopics/assets/PDF/AIMag26-04-016.pdf" target="_blank" rel="noopener">A (Very) Brief History of Artificial Intelligence</a></div><div class="ref-meta">Buchanan, B.G.</div><p class="ref-desc">紧凑的 8 页历史，适合备课。覆盖各主要时代。</p></div></li><li class="ref-item" id="ref-A6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A6</span><span class="ref-title"><strong>How to Dispel Your Illusions</strong> (review of <em>Thinking, Fast and Slow</em>)</span></div><div class="ref-meta">Freeman Dyson</div><p class="ref-desc"><a href="https://www.nybooks.com/articles/2011/12/22/how-dispel-your-illusions/" target="_blank" rel="noopener">nybooks.com</a></p></div></li><li class="ref-item" id="ref-A7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A7</span><span class="ref-title">Invisible Manipulators of Your Mind</span></div><div class="ref-meta">Tamsin Shaw</div><p class="ref-desc"><a href="https://www.nybooks.com/articles/2017/04/20/kahneman-tversky-invisible-mind-manipulators/" target="_blank" rel="noopener">nybooks.com</a></p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="课堂互动实验">5. 课堂互动实验</h2><h3 class="ref-group" id="课堂互动实验--实验-1-锚定效应-约-3-分钟">实验 1：锚定效应（约 3 分钟）</h3><p class="ref-prose"><strong>来源</strong>：Tversky &amp; Kahneman (1974)；<em>Thinking, Fast and Slow</em> 第 11 章</p><p class="ref-prose"><strong>做法</strong>：把听众分成两组（教室左 / 右两侧）。</p><p class="ref-prose">- A 组：&quot;甘地去世时年龄是大于还是小于 <strong>114</strong> 岁？他多少岁？&quot;</p><p class="ref-prose">- B 组：&quot;甘地去世时年龄是大于还是小于 <strong>35</strong> 岁？他多少岁？&quot;</p><p class="ref-prose"><strong>结果</strong>：A 组的估计始终更高。无关的锚点数字污染了他们的判断。</p><p class="ref-prose"><strong>点睛</strong>：&quot;你的 System 1 被一个你明知错误的数字锚住了。&quot;</p><h3 class="ref-group" id="课堂互动实验--实验-2-linda-问题-合取谬误-约-3-分钟">实验 2：Linda 问题 / 合取谬误（约 3 分钟）</h3><p class="ref-prose"><strong>来源</strong>：Tversky &amp; Kahneman (1983)</p><p class="ref-prose"><strong>做法</strong>：念出：&quot;Linda 31 岁，未婚、直率、聪明。哲学专业，学生时代关心歧视与社会公正问题。&quot;</p><p class="ref-prose">提问：&quot;哪种更可能？(A) Linda 是银行柜员。(B) Linda 是银行柜员且积极参与女权运动。&quot;</p><p class="ref-prose"><strong>结果</strong>：约 85% 选 B，违反合取规则（P(A∧B) ≤ P(A)）。</p><p class="ref-prose"><strong>点睛</strong>：&quot;你的大脑用&#39;哪个更像 Linda？&#39;替换了&#39;哪个更可能？&#39;——这就是属性替换，这就是 System 1。&quot;</p><h3 class="ref-group" id="课堂互动实验--实验-3-视觉盲点演示-约-2-分钟">实验 3：视觉盲点演示（约 2 分钟）</h3><p class="ref-prose"><strong>做法</strong>：投影一张图，左为十字（+）、右为圆点（●），相距约 15cm。让学生闭右眼、盯十字，慢慢前后移动相对屏幕的距离。</p><p class="ref-prose"><strong>结果</strong>：圆点会在某个距离消失——大脑会自行补上缺口。</p><p class="ref-prose"><strong>点睛</strong>：&quot;你的大脑此刻就在编造视觉数据。它是预测机器，不是相机。&quot;</p><h3 class="ref-group" id="课堂互动实验--实验-4-球棒-球问题-约-2-分钟">实验 4：球棒-球问题（约 2 分钟）</h3><p class="ref-prose"><strong>来源</strong>：Frederick (2005) 认知反射测试；Kahneman (2003)</p><p class="ref-prose"><strong>做法</strong>：&quot;球棒和球加起来 $1.10。球棒比球贵 $1.00。球多少钱？&quot;</p><p class="ref-prose"><strong>结果</strong>：多数人脱口而出 &quot;$0.10&quot;（错——正确答案是 $0.05）。</p><p class="ref-prose"><strong>点睛</strong>：&quot;System 1 给了你一个自信、快速、错误的答案。System 2 懒得核查。你大部分思考都是这样运作的。&quot;</p><h3 class="ref-group" id="课堂互动实验--实验-5-框架效应-约-2-分钟">实验 5：框架效应（约 2 分钟）</h3><p class="ref-prose"><strong>来源</strong>：Tversky &amp; Kahneman (1981)</p><p class="ref-prose"><strong>做法</strong>：再次把听众分成两组。</p><p class="ref-prose">- A 组：&quot;将有 600 人因某疾病死亡。方案 A 可救 200 人。&quot;</p><p class="ref-prose">- B 组：&quot;将有 600 人死亡。方案 B 有 1/3 概率无人死、2/3 概率 600 人全死。&quot;</p><p class="ref-prose"><strong>结果</strong>：约 72% 选 A（确定救 200 人）；约 78% 选 B（赌一把）。<strong>但 A 和 B 在数学上完全等价。</strong></p><p class="ref-prose"><strong>点睛</strong>：&quot;同样的信息，不同的框架，相反的决策。你的&#39;理性心智&#39;只是神话。&quot;</p><h3 class="ref-group" id="课堂互动实验--实验-6-模式识别-聚类错觉-约-2-分钟">实验 6：模式识别 / 聚类错觉（约 2 分钟）</h3><p class="ref-prose"><strong>来源</strong>：Gilovich, Vallone &amp; Tversky (1985) ——&quot;热手&quot;论文</p><p class="ref-prose"><strong>做法</strong>：展示两段抛硬币序列：HHHTTTHHHTTT vs. HTTHHTTHHTHT。提问：&quot;哪个是随机的？&quot;</p><p class="ref-prose"><strong>结果</strong>：人们会判定看起来&quot;交替&quot;的序列&quot;更随机&quot;，尽管两段同样可能。</p><p class="ref-prose"><strong>点睛</strong>：&quot;你的大脑会在噪声里看见模式。这正是迷信的来源——也是神经网络学会做的同一件事。&quot;</p><h3 class="ref-group" id="课堂互动实验--实验-7-看不见的大猩猩-约-1-分钟-播放视频">实验 7：看不见的大猩猩（约 1 分钟，播放视频）</h3><p class="ref-prose"><strong>来源</strong>：Simons &amp; Chabris (1999)</p><p class="ref-prose"><strong>做法</strong>：播放著名的&quot;数篮球传球次数&quot;视频。</p><p class="ref-prose"><strong>结果</strong>：约 50% 的观众没有注意到画面中走过的大猩猩。</p><p class="ref-prose"><strong>点睛</strong>：&quot;注意力是资源。System 1 在无情过滤。你没注意到的东西，你真的就看不见。&quot;</p><p class="ref-prose"><strong>链接</strong>：<a href="http://www.theinvisiblegorilla.com/" target="_blank" rel="noopener">theinvisiblegorilla.com</a></p><h3 class="ref-group" id="课堂互动实验--实验-8-可得性启发-死因估计-约-2-分钟">实验 8：可得性启发——死因估计（约 2 分钟）</h3><p class="ref-prose"><strong>来源</strong>：Tversky &amp; Kahneman (1973)</p><p class="ref-prose"><strong>做法</strong>：&quot;每年死亡人数更多的是鲨鱼袭击还是椰子掉落？空难还是车祸？恐袭还是糖尿病？&quot;</p><p class="ref-prose"><strong>结果</strong>：人们系统性地高估戏剧化、上新闻的死因，低估日常死因。</p><p class="ref-prose"><strong>点睛</strong>：&quot;你按&#39;回忆的难易&#39;估计频率。媒体曝光 = 可得性 = 感知到的危险。你的大脑是被新闻加权的预测器。&quot;</p></section><section class="ref-card"><h2 class="ref-card-title" id="历史素材-ai-流派之争-70-年的下注">6. 历史素材：AI 流派之争（&quot;70 年的下注&quot;）</h2><h3 class="ref-group" id="历史素材-ai-流派之争-70-年的下注--四大流派">四大流派</h3><ol class="ref-list"><li class="ref-item" id="ref-S6-1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"><strong>Symbolic AI</strong> (符号派)</span></div><div class="ref-meta">McCarthy, Newell, Simon, Minsky (early) · 1956–1980s</div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">核心赌注：</span>&quot;智能 = 符号操作 + 逻辑&quot;</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">关键文献：</span>Dartmouth Workshop proposal (McCarthy et al., 1955); Logic Theorist (Newell &amp; Simon, 1956); Minsky &amp; Papert, <em>Perceptrons</em> (1969)</p></div></li><li class="ref-item" id="ref-S6-2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"><strong>Connectionist</strong> (连接派)</span></div><div class="ref-meta">Rosenblatt, Rumelhart, Hinton, LeCun · 1943, revival 1986+</div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">核心赌注：</span>&quot;智能 = 通过神经网络从数据中学习&quot;</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">关键文献：</span>McCulloch &amp; Pitts (1943); Rosenblatt&#39;s Perceptron (1958); <em>Parallel Distributed Processing</em> (Rumelhart &amp; McClelland, 1986); Backpropagation revival</p></div></li><li class="ref-item" id="ref-S6-3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"><strong>Big Data / Statistical</strong> (大数据派)</span></div><div class="ref-meta">Norvig, Halevy, Pereira · 2000s–2010s</div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">核心赌注：</span>&quot;智能 = 足够的数据 + 简单的模型&quot;</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">关键文献：</span>&quot;The Unreasonable Effectiveness of Data&quot; (Halevy, Norvig &amp; Pereira, 2009); IBM Watson (2011); word2vec (Mikolov et al., 2013)</p></div></li><li class="ref-item" id="ref-S6-4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"><strong>Scaling / Large Models</strong> (大模型派)</span></div><div class="ref-meta">Sutskever, Kaplan, OpenAI, Google Brain · 2017–present</div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">核心赌注：</span>&quot;智能 = 规模（算力 × 数据 × 参数）&quot;</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">关键文献：</span>&quot;Attention Is All You Need&quot; (Vaswani et al., 2017); GPT series; Scaling Laws (Kaplan et al., 2020); Chinchilla (Hoffmann et al., 2022)</p></div></li></ol><h3 class="ref-group" id="历史素材-ai-流派之争-70-年的下注--叙事所需的关键历史时刻">叙事所需的关键历史时刻</h3><ol class="ref-list"><li class="ref-item" id="ref-S6-5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">McCulloch &amp; Pitts paper</span></div><div class="ref-meta">McCulloch &amp; Pitts 1943 · 1943</div><p class="ref-desc">首个神经元的计算模型</p></div></li><li class="ref-item" id="ref-S6-6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Dartmouth Workshop</span></div><div class="ref-meta">McCarthy et al. 1955 proposal; McCorduck 2004, pp. 111–136 · 1956</div><p class="ref-desc">AI 作为学科确立。符号派获得初期资助。</p></div></li><li class="ref-item" id="ref-S6-7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Rosenblatt&#39;s Perceptron</span></div><div class="ref-meta">Crevier 1993, pp. 102–105 · 1958</div><p class="ref-desc">首台学习机。Rosenblatt 预言它会&quot;学习、决策、翻译语言&quot;。</p></div></li><li class="ref-item" id="ref-S6-8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Minsky &amp; Papert&#39;s <em>Perceptrons</em></span></div><div class="ref-meta">Minsky &amp; Papert 1969; Russell &amp; Norvig 2021, p. 22 · 1969</div><p class="ref-desc">证明单层网络的局限。让神经网络资助断档十年。</p></div></li><li class="ref-item" id="ref-S6-9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">First AI Winter</span></div><div class="ref-meta">Lighthill 1973; Crevier 1993 · 1974–80</div><p class="ref-desc">符号派 AI 无法规模化。英国 Lighthill 报告（1973）。DARPA 削减资助。</p></div></li><li class="ref-item" id="ref-S6-10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Expert Systems Boom</span></div><div class="ref-meta">Crevier 1993, pp. 161–203; Russell &amp; Norvig 2021, p. 23 · 1980–87</div><p class="ref-desc">符号派 AI 的商业巅峰。产业规模从百万级跃升到十亿级。</p></div></li><li class="ref-item" id="ref-S6-11"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Backpropagation revival</span></div><div class="ref-meta">Rumelhart &amp; McClelland 1986; Russell &amp; Norvig 2021, p. 24 · 1986</div><p class="ref-desc">Rumelhart &amp; Hinton 让反向传播流行起来。连接派复兴。Hinton 称符号是&quot;AI 的发光以太&quot;。</p></div></li><li class="ref-item" id="ref-S6-12"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Judea Pearl&#39;s <em>Probabilistic Reasoning</em></span></div><div class="ref-meta">Pearl 1988 · 1988</div><p class="ref-desc">概率进入 AI。统计方法逐渐占据主流。</p></div></li><li class="ref-item" id="ref-S6-13"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">LeCun&#39;s ConvNets read zip codes</span></div><div class="ref-meta">Russell &amp; Norvig 2021, p. 26 · 1990</div><p class="ref-desc">首个真正有用的神经网络应用。</p></div></li><li class="ref-item" id="ref-S6-14"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Second AI Winter</span></div><div class="ref-meta">Russell &amp; Norvig 2021, p. 24–25 · 1990–2000</div><p class="ref-desc">专家系统崩盘。研究者不再称自己工作为&quot;AI&quot;。</p></div></li><li class="ref-item" id="ref-S6-15"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Hinton&#39;s &quot;Deep Belief Networks&quot;</span></div><div class="ref-meta">Hinton, Osindero &amp; Teh 2006 · 2006</div><p class="ref-desc">深度学习开始崛起。</p></div></li><li class="ref-item" id="ref-S6-16"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">IBM Watson wins Jeopardy!</span></div><div class="ref-meta">Russell &amp; Norvig 2021, p. 26 · 2011</div><p class="ref-desc">大数据路线在自然语言问答中获胜。</p></div></li><li class="ref-item" id="ref-S6-17"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">AlexNet wins ImageNet</span></div><div class="ref-meta">Krizhevsky, Sutskever &amp; Hinton 2012 · 2012</div><p class="ref-desc">深度学习碾压计算机视觉基准。大坝决堤。</p></div></li><li class="ref-item" id="ref-S6-18"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">&quot;Attention Is All You Need&quot;</span></div><div class="ref-meta">Vaswani et al. 2017 · 2017</div><p class="ref-desc">Transformer 架构。此后一切的基础。</p></div></li><li class="ref-item" id="ref-S6-19"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">GPT-3</span></div><div class="ref-meta">Brown et al. 2020 · 2020</div><p class="ref-desc">1750 亿参数。涌现的 few-shot 学习。规模化下注得到惊人回报。</p></div></li><li class="ref-item" id="ref-S6-20"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">ChatGPT, GPT-4, Claude, etc.</span></div><div class="ref-meta">2022–present</div><p class="ref-desc">大模型进入主流。规模派的时刻。</p></div></li><li class="ref-item" id="ref-S6-21"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Nobel Prize to Hopfield &amp; Hinton</span></div><div class="ref-meta">Nobel Committee 2024 · 2024</div><p class="ref-desc">连接派的下注在最高层面得到认可。</p></div></li></ol><h3 class="ref-group" id="历史素材-ai-流派之争-70-年的下注--70-年-片段的叙事弧-约-5-10-分钟">&quot;70 年&quot;片段的叙事弧（约 5–10 分钟）</h3><p class="ref-prose">&gt; <strong>总框架</strong>：&quot;每一代 AI 研究者都对智能的本质下了一个赌注。&quot;</p><p class="ref-prose">&gt;</p><p class="ref-prose">&gt; 1. <strong>1950s–60s</strong>：符号派下注&quot;智能 = 逻辑 + 规则&quot;，获得初期资助。Rosenblatt 的感知机被冷落。</p><p class="ref-prose">&gt; 2. <strong>1970s–80s</strong>：符号 AI 撞墙（组合爆炸、常识知识问题）。第一次 AI 寒冬。专家系统短暂复兴。</p><p class="ref-prose">&gt; 3. <strong>1986</strong>：连接派回归。Hinton 与 Rumelhart 证明网络能学习。&quot;范式之战&quot;——Hinton 称符号是&quot;发光以太&quot;。</p><p class="ref-prose">&gt; 4. <strong>1990s–2000s</strong>：统计方法悄然取胜。ML 社区认识到：<strong>数据 &gt; 手工规则</strong>。没人叫它 AI——他们叫&quot;机器学习&quot;。</p><p class="ref-prose">&gt; 5. <strong>2012–2017</strong>：深度学习爆发。更多数据 + 更多算力 = 更好性能。Transformer 登场。</p><p class="ref-prose">&gt; 6. <strong>2020–至今</strong>：规模派的下注。GPT-3/4 证明&quot;足够的算力 × 足够的数据&quot;会产生*看起来像*智能的东西。2024 年 Hinton 获诺奖。</p><p class="ref-prose">&gt;</p><p class="ref-prose">&gt; <strong>点睛</strong>：&quot;四大流派问的是同一个问题——<em>怎样计算智能？</em> 答案是：用你大脑一直在用的方式——把海量经验压缩成快速、近似、通常正确的预测。这就是 System 1，也是神经网络在做的事。&quot;</p></section><section class="ref-card"><h2 class="ref-card-title" id="补充资源">7. 补充资源</h2><h3 class="ref-group" id="补充资源--课堂演示网站">课堂演示网站</h3><p class="ref-prose">- <strong>The Invisible Gorilla</strong>：<a href="http://www.theinvisiblegorilla.com/" target="_blank" rel="noopener">theinvisiblegorilla.com</a> — 选择性注意演示</p><p class="ref-prose">- <strong>Annenberg Learner：决策与可得性启发式</strong>：<a href="https://www.learner.org/series/discovering-psychology/judgement-and-decision-making/" target="_blank" rel="noopener">learner.org</a> — 互动练习</p><p class="ref-prose">- <strong>视错觉合集</strong>：<a href="https://michaelbach.de/ot/" target="_blank" rel="noopener">michaelbach.de/ot/</a> — 全面的视错觉演示</p><h3 class="ref-group" id="补充资源--重点-wikipedia-页面-维护良好-适合快速参考">重点 Wikipedia 页面（维护良好，适合快速参考）</h3><p class="ref-prose">- <a href="https://en.wikipedia.org/wiki/List_of_cognitive_biases" target="_blank" rel="noopener">List of cognitive biases</a> — 全面，按任务类型组织</p><p class="ref-prose">- <a href="https://en.wikipedia.org/wiki/Thinking,_Fast_and_Slow" target="_blank" rel="noopener">Thinking, Fast and Slow</a> — 章节级别的良好摘要</p><p class="ref-prose">- <a href="https://en.wikipedia.org/wiki/History_of_artificial_intelligence" target="_blank" rel="noopener">History of artificial intelligence</a> — 详尽、有出处</p><p class="ref-prose">- <a href="https://en.wikipedia.org/wiki/Heuristic_(psychology" target="_blank" rel="noopener">Heuristic (psychology)</a>) — 同时覆盖形式化与非形式化启发式模型</p><h3 class="ref-group" id="补充资源--认知反射测试-crt">认知反射测试（CRT）</h3><p class="ref-prose"><strong>来源</strong>：Frederick, S. (2005). &quot;Cognitive Reflection and Decision Making.&quot; <em>Journal of Economic Perspectives</em>, 19(4), 25–42.</p><p class="ref-prose">三道能稳定区分 System 1 / System 2 思考者的题目：</p><p class="ref-prose">1. 球棒-球（共 $1.10，球棒比球贵 $1）</p><p class="ref-prose">2. 工件机器（5 台机器 5 分钟做 5 件 → 100 台机器做 100 件需要多久？）</p><p class="ref-prose">3. 睡莲倍增（第 47 天覆盖湖面一半 → 第几天覆盖整个湖面？）</p></section><section class="ref-card"><h2 class="ref-card-title" id="速查-本讲-top-10-资源">速查：本讲 Top 10 资源</h2><ol class="ref-list"><li class="ref-item" id="ref-S8-1"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Kahneman — <em>Thinking, Fast and Slow</em>, Parts I–II</span></div><p class="ref-desc">System 1/2 框架，覆盖所有主要演示</p></div></li><li class="ref-item" id="ref-S8-2"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Tversky &amp; Kahneman (1974) — &quot;Judgment under Uncertainty&quot;</span></div><p class="ref-desc">奠基论文</p></div></li><li class="ref-item" id="ref-S8-3"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Korteling et al. (2018) — Neural Network Framework for Cognitive Bias</span></div><p class="ref-desc">把偏误连接到神经网络</p></div></li><li class="ref-item" id="ref-S8-4"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-title">McCorduck (2004) — <em>Machines Who Think</em></span></div><p class="ref-desc">最佳的 AI 历史叙事</p></div></li><li class="ref-item" id="ref-S8-5"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-title">The Invisible Gorilla video</span></div><p class="ref-desc">难忘的课堂演示</p></div></li><li class="ref-item" id="ref-S8-6"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Veritasium: The Bayesian Trap</span></div><p class="ref-desc">可得性启发式的精彩讲解</p></div></li><li class="ref-item" id="ref-S8-7"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Russell &amp; Norvig (2021), Ch.1</span></div><p class="ref-desc">AI 范式概览</p></div></li><li class="ref-item" id="ref-S8-8"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Frederick (2005) — Cognitive Reflection Test</span></div><p class="ref-desc">球棒-球问题</p></div></li><li class="ref-item" id="ref-S8-9"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Gigerenzer (2009) — Homo Heuristicus</span></div><p class="ref-desc">反方观点：偏误作为特性</p></div></li><li class="ref-item" id="ref-S8-10"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-title">Hilbert (2012) — Synthesis of Cognitive Biases</span></div><p class="ref-desc">统一的含噪处理框架</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="把-llm-当作-认知被试-的近年论文-2023-2026">8. 把 LLM 当作&quot;认知被试&quot;的近年论文（2023–2026）</h2><p class="ref-prose">&gt; 这一节是 2023 年后兴起的新研究方向：把 LLM 当成&quot;心理被试&quot;来跑经典认知偏误实验。</p><p class="ref-prose">&gt; 它们直接支撑本讲后半段：&quot;如果人类的偏见来自统计学习，LLM 也应该有同样的偏见——而它们确实有。&quot;</p><ol class="ref-list"><li class="ref-item" id="ref-P17"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P17</span><a class="ref-title" href="https://arxiv.org/abs/2206.14576" target="_blank" rel="noopener">Using cognitive psychology to understand GPT-3</a></div><div class="ref-meta">Binz &amp; Schulz · 2023</div><p class="ref-desc">标志性论文。把 GPT-3 跑了 Linda Problem、Cognitive Reflection Test 等 12 项经典认知任务——结果几乎复现了人类的全部经典偏误。直接喂给本讲。</p></div></li><li class="ref-item" id="ref-P18"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P18</span><a class="ref-title" href="https://www.nature.com/articles/s41586-025-09215-4" target="_blank" rel="noopener">Centaur: a foundation model of human cognition</a></div><div class="ref-meta">Binz et al. · 2024</div><div class="ref-links"><a class="ref-link" href="https://arxiv.org/abs/2410.20268" target="_blank" rel="noopener">arXiv:2410.20268</a></div><p class="ref-desc">Binz 团队后续：用 Llama-70B + 1 万人类心理实验数据 LoRA 微调，得到能预测任意人类决策的&quot;通用心理学模型&quot;。Nature 发表。</p></div></li><li class="ref-item" id="ref-P19"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P19</span><a class="ref-title" href="https://arxiv.org/abs/2301.07543" target="_blank" rel="noopener">Large Language Models as Simulated Economic Agents: What Can We Learn from Homo Silicus?</a></div><div class="ref-meta">Horton · 2023</div><p class="ref-desc">哈佛经济学家用 GPT 复现 Kahneman 经典实验。&quot;Homo Silicus&quot; 一词由此而来。</p></div></li><li class="ref-item" id="ref-P20"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P20</span><a class="ref-title" href="https://arxiv.org/abs/2305.07970" target="_blank" rel="noopener">Behavioral Economics of LLMs: Evidence of Risk and Time Preferences</a></div><div class="ref-meta">Chen, Liu, et al. · 2023-24</div><p class="ref-desc">LLM 表现出和人类相似的风险厌恶 + 时间贴现模式。</p></div></li><li class="ref-item" id="ref-P21"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P21</span><a class="ref-title" href="https://arxiv.org/abs/2309.12288" target="_blank" rel="noopener">The Reversal Curse: LLMs trained on &quot;A is B&quot; fail to learn &quot;B is A&quot;</a></div><div class="ref-meta">Berglund et al. · 2023</div><p class="ref-desc">LLM 的&quot;非对称记忆&quot;——本身就是一种系统性认知偏误。本讲可作为&quot;机器也有它自己的偏误&quot;案例。</p></div></li><li class="ref-item" id="ref-P22"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P22</span><a class="ref-title" href="https://arxiv.org/abs/2309.13638" target="_blank" rel="noopener">Embers of Autoregression: Understanding Large Language Models Through the Problem They Are Trained to Solve</a></div><div class="ref-meta">McCoy, Yao et al. · 2023</div><p class="ref-desc">普林斯顿研究：LLM 失败模式与训练任务（next-token prediction）的统计分布直接相关——&quot;它做不好的事，正是训练数据里少见的事&quot;。</p></div></li><li class="ref-item" id="ref-P23"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P23</span><a class="ref-title" href="https://arxiv.org/abs/2412.06593" target="_blank" rel="noopener">Anchoring Bias in Large Language Models: An Experimental Study</a></div><div class="ref-meta">Lou et al. · 2024</div><p class="ref-desc">复现锚定效应于 GPT-4 / Claude / Llama。可直接做本讲互动实验的&quot;机器版&quot;。</p></div></li><li class="ref-item" id="ref-P24"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P24</span><a class="ref-title" href="https://arxiv.org/abs/2410.15413" target="_blank" rel="noopener">A Comprehensive Evaluation of Cognitive Biases in LLMs</a></div><div class="ref-meta">2024</div><p class="ref-desc">系统测试 30+ 经典偏误于 8 种 LLM。建了首个&quot;机器认知偏误 benchmark&quot;。</p></div></li><li class="ref-item" id="ref-P25"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P25</span><a class="ref-title" href="https://aclanthology.org/2024.acl-long.770/" target="_blank" rel="noopener">Confabulation: The Surprising Value of Large Language Model Hallucinations</a></div><div class="ref-meta">Sui et al. · 2024</div><p class="ref-desc">把 LLM hallucination 重新框架为&quot;confabulation&quot;（人类失忆症患者也会做的事）。神经科学 × NLP 跨界。</p></div></li><li class="ref-item" id="ref-P26"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P26</span><a class="ref-title" href="https://arxiv.org/abs/2311.00059" target="_blank" rel="noopener">The Generative AI Paradox: &quot;What It Can Create, It May Not Understand&quot;</a></div><div class="ref-meta">West, Lu, Dziri et al. · 2024</div><p class="ref-desc">AI2 + UW 研究：LLM 生成质量 ≠ 理解能力。直接呼应本讲核心问题。</p></div></li><li class="ref-item" id="ref-P27"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P27</span><a class="ref-title" href="https://arxiv.org/abs/2402.16837" target="_blank" rel="noopener">Do Large Language Models Latently Perform Multi-Hop Reasoning?</a></div><div class="ref-meta">Yang et al. (DeepMind) · 2024</div><p class="ref-desc">DeepMind 探针实验：LLM 内部隐式做多跳推理——给&quot;它在思考吗&quot;提供机制证据。</p></div></li><li class="ref-item" id="ref-P28"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P28</span><a class="ref-title" href="https://arxiv.org/abs/2304.15004" target="_blank" rel="noopener">Are Emergent Abilities of Large Language Models a Mirage?</a></div><div class="ref-meta">Schaeffer, Miranda, Koyejo · 2023</div><p class="ref-desc">反方观点：所谓&quot;涌现能力&quot;是评测指标人为造成的台阶。重要的祛魅文献。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="关于机器-认知-的产业讲座与深度评述-2023-2026">9. 关于机器&quot;认知&quot;的产业讲座与深度评述（2023–2026）</h2><ol class="ref-list"><li class="ref-item" id="ref-T1"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T1</span><a class="ref-title" href="https://www.youtube.com/results?search_query=lecun+limits+llm" target="_blank" rel="noopener">The Limits of LLMs and What Comes Next</a></div><div class="ref-meta">Yann LeCun (NYU/Meta) · 2024</div><p class="ref-desc">LeCun 反复强调 &quot;LLMs cannot reason / plan / understand the physical world.&quot; 用作本讲&quot;机器认知 ≠ 人类认知&quot;的反方观点。</p></div></li><li class="ref-item" id="ref-T2"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T2</span><a class="ref-title" href="https://openreview.net/forum?id=BZ5a1r-kVsf" target="_blank" rel="noopener">A Path Towards Autonomous Machine Intelligence (JEPA)</a></div><div class="ref-meta">Yann LeCun · 2022-25</div><div class="ref-links"><a class="ref-link" href="https://ai.meta.com/blog/yann-lecun-ai-model-i-jepa/" target="_blank" rel="noopener">Meta blog</a></div><p class="ref-desc">LeCun 的&quot;世界模型&quot;路线图。给&quot;System 2 应该怎么实现&quot;提供候选答案。</p></div></li><li class="ref-item" id="ref-T3"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T3</span><span class="ref-title"><strong>The Hidden Cost of LLM Cognition</strong> (NeurIPS 2024 invited talk)</span></div><div class="ref-meta">Anna Rumshisky / various · 2024</div><p class="ref-desc">神经科学家眼中的 LLM&quot;思维成本&quot;。</p></div></li><li class="ref-item" id="ref-T4"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T4</span><a class="ref-title" href="https://arxiv.org/abs/2305.15038" target="_blank" rel="noopener"><strong>Is GPT-4 a Good Data Analyst?</strong> (live-demoing biased reasoning)</a></div><div class="ref-meta">Cheng, Chen, et al. · 2024</div><p class="ref-desc">实测 LLM 在数据分析任务中犯哪些&quot;统计直觉&quot;型错误。</p></div></li><li class="ref-item" id="ref-T5"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T5</span><a class="ref-title" href="https://www.dwarkesh.com/p/sholto-trenton" target="_blank" rel="noopener">Sholto Douglas &amp; Trenton Bricken (Anthropic) on Anthropic&#39;s Research</a></div><div class="ref-meta">Dwarkesh Patel Podcast · 2024</div><p class="ref-desc">4 小时长访谈，Anthropic 顶尖研究员讲&quot;模型内部到底在做什么&quot;。机制可解释性视角。</p></div></li><li class="ref-item" id="ref-T6"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T6</span><a class="ref-title" href="https://www.cbsnews.com/news/godfather-of-artificial-intelligence-weighs-in-on-the-past-and-potential-of-artificial-intelligence/" target="_blank" rel="noopener">Geoffrey Hinton: AI&#39;s Dangers + Why It Might Be Sentient</a></div><div class="ref-meta">60 Minutes / various · 2023-24</div><p class="ref-desc">Hinton 离开 Google 后系列采访。直接谈&quot;神经网络可能比人类更好地理解世界&quot;。</p></div></li><li class="ref-item" id="ref-T7"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T7</span><a class="ref-title" href="https://www.nobelprize.org/prizes/physics/2024/hinton/lecture/" target="_blank" rel="noopener">Geoffrey Hinton — Nobel Prize Lecture</a></div><div class="ref-meta">Hinton · 2024</div><p class="ref-desc">Hinton 的诺贝尔物理学奖讲座。从 Boltzmann 机讲到当代 LLM——本讲&quot;70 年&quot;叙事的官方收尾。</p></div></li><li class="ref-item" id="ref-T8"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T8</span><a class="ref-title" href="https://www.youtube.com/watch?v=AKMuA_TVz3A" target="_blank" rel="noopener"><strong>Sutskever: An Observation on Generalization</strong> (Simons Institute)</a></div><div class="ref-meta">Ilya Sutskever · 2023</div><p class="ref-desc">&quot;Predict next token&quot; → 涌现智能的完整论证。本讲的&quot;机器一侧&quot;哲学基础。</p></div></li><li class="ref-item" id="ref-T9"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T9</span><span class="ref-title"><strong>Demis Hassabis on the Path to AGI</strong> (Tribeca / various)</span></div><div class="ref-meta">Demis Hassabis · 2024-25</div><p class="ref-desc">DeepMind 路线图：Game → Science → AGI。</p></div></li><li class="ref-item" id="ref-T10"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T10</span><a class="ref-title" href="https://deepmind.google/discover/blog/welcome-to-the-era-of-experience/" target="_blank" rel="noopener">Welcome to the Era of Experience</a></div><div class="ref-meta">David Silver, Richard Sutton · 2025</div><p class="ref-desc">Silver/Sutton 联名宣言：&quot;数据时代结束，经验时代开始&quot;。挑战 LLM 路线。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="技术博客与长文-2023-2026">10. 技术博客与长文（2023–2026）</h2><ol class="ref-list"><li class="ref-item" id="ref-A8"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A8</span><a class="ref-title" href="https://writings.stephenwolfram.com/2023/02/what-is-chatgpt-doing-and-why-does-it-work/" target="_blank" rel="noopener"><strong>Why ChatGPT-style LLMs Hallucinate</strong> (and what to do about it)</a></div><div class="ref-meta">Stephen Wolfram · 2023</div><p class="ref-desc">长篇科普。把&quot;LLM 在做什么&quot;翻译成数学和物理直觉。中段大量类比人脑直觉。</p></div></li><li class="ref-item" id="ref-A9"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A9</span><a class="ref-title" href="https://x.com/karpathy/status/1733299213503787018" target="_blank" rel="noopener">Hallucinations are not Bugs, they are Features</a></div><div class="ref-meta">Various essays + Andrej Karpathy tweets · 2023-24</div><p class="ref-desc">&quot;LLM 永远在 hallucinate，只不过它学会了让 hallucination 和现实一致。&quot; 本讲核心隐喻。</p></div></li><li class="ref-item" id="ref-A10"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A10</span><a class="ref-title" href="https://huyenchip.com/2023/05/02/rlhf.html" target="_blank" rel="noopener">The Illustrated Reinforcement Learning from Human Feedback (RLHF)</a></div><div class="ref-meta">Chip Huyen · 2023</div><p class="ref-desc">把&quot;训练 LLM 像训练 System 1&quot;的隐喻可视化。</p></div></li><li class="ref-item" id="ref-A11"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A11</span><span class="ref-title">Why Models Hallucinate: An Information-Theoretic View</span></div><div class="ref-meta">Lance Eliot / various · 2024</div><p class="ref-desc">信息论视角。</p></div></li><li class="ref-item" id="ref-A12"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A12</span><a class="ref-title" href="https://huyenchip.com/2024/03/14/ai-oss.html" target="_blank" rel="noopener">What I Learned from Looking at 900 Most Popular Open Source AI Tools</a></div><div class="ref-meta">Chip Huyen · 2024</div><p class="ref-desc">当代 AI 生态全景。给&quot;机器认知是工程系统&quot;的视角。</p></div></li><li class="ref-item" id="ref-A13"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A13</span><a class="ref-title" href="https://knightcolumbia.org/content/ai-as-normal-technology" target="_blank" rel="noopener">AI as Normal Technology</a></div><div class="ref-meta">Arvind Narayanan &amp; Sayash Kapoor · 2024</div><p class="ref-desc">普林斯顿团队反对&quot;AI 即将取代人类&quot;叙事。&quot;机器智能不是魔法，是又一种技术。&quot;</p></div></li><li class="ref-item" id="ref-A14"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A14</span><a class="ref-title" href="http://www.incompleteideas.net/IncIdeas/BitterLesson.html" target="_blank" rel="noopener"><strong>The Bitter Lesson</strong> (re-read for cognitive bias context)</a></div><div class="ref-meta">Richard Sutton · 2019</div><p class="ref-desc">经典短文。在本讲语境下：研究者反复用&quot;领域知识&quot;建模人类认知，结果都被&quot;统计 + 算力&quot;打败。</p></div></li><li class="ref-item" id="ref-A15"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A15</span><a class="ref-title" href="https://arxiv.org/abs/2308.03762" target="_blank" rel="noopener"><strong>GPT-4 Can&#39;t Reason</strong> (and how to argue about it)</a></div><div class="ref-meta">Subbarao Kambhampati / various · 2023-24</div><p class="ref-desc">反方观点。给学生看&quot;是否会推理&quot;是开放争论。</p></div></li><li class="ref-item" id="ref-A16"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A16</span><a class="ref-title" href="https://arxiv.org/abs/2303.12712" target="_blank" rel="noopener"><strong>Sparks of AGI</strong> (the prompt is doing the reasoning)</a></div><div class="ref-meta">Bubeck et al. (Microsoft) · 2023</div><p class="ref-desc">已在 P16 列出，但博客版本 + 社区争议同样重要。</p></div></li><li class="ref-item" id="ref-A17"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A17</span><a class="ref-title" href="https://transformer-circuits.pub/" target="_blank" rel="noopener"><strong>Anthropic Interpretability Posts</strong> (Toy Models, Monosemanticity, Scaling Monosemanticity)</a></div><div class="ref-meta">Anthropic Interpretability Team · 2022-25</div><p class="ref-desc">&quot;我们打开 Claude 的大脑发现了什么&quot;系列。把&quot;机器认知&quot;从黑盒变白盒的最前沿。</p></div></li><li class="ref-item" id="ref-A18"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A18</span><a class="ref-title" href="https://replicationindex.com/" target="_blank" rel="noopener">The 2024 Replication Crisis Update on Priming</a></div><div class="ref-meta">Replication Index / Ulrich Schimmack · 2024</div><p class="ref-desc">重要：&quot;Thinking, Fast and Slow&quot; Ch.4 priming 章节大量未通过复现——讲座必须如实告知。</p></div></li><li class="ref-item" id="ref-A19"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A19</span><span class="ref-title"><strong>What is it Like to Be ChatGPT?</strong> (Phenomenology of LLMs)</span></div><div class="ref-meta">2023-24</div><p class="ref-desc">哲学向。给&quot;机器有体验吗&quot;讨论提供入口。</p></div></li><li class="ref-item" id="ref-A20"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A20</span><a class="ref-title" href="https://www.aisnakeoil.com/" target="_blank" rel="noopener"><strong>The AI Snake Oil newsletter / book</strong> (2024)</a></div><div class="ref-meta">Narayanan &amp; Kapoor · 2024</div><p class="ref-desc">指出 &quot;AI 能力&quot; 在哪些场景被高估。讲述&quot;什么是预测，什么不是&quot;的产业警示。</p></div></li><li class="ref-item" id="ref-A21"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A21</span><a class="ref-title" href="https://simonwillison.net/series/llms-in-2024/" target="_blank" rel="noopener">Things We Learned About LLMs in 2024 / 2025</a></div><div class="ref-meta">Simon Willison · 2024 / 2025</div><p class="ref-desc">必读年度回顾。本讲 70 年叙事的最近一格。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="关于心智-大脑与机器的近年书籍-2022-2026">11. 关于心智、大脑与机器的近年书籍（2022–2026）</h2><ol class="ref-list"><li class="ref-item" id="ref-B13"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B13</span><span class="ref-title">The Worlds I See</span></div><div class="ref-meta">Fei-Fei Li · 2023</div><p class="ref-desc">ImageNet 创始人自传。第一手讲&quot;为什么数据是关键&quot;。</p></div></li><li class="ref-item" id="ref-B14"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B14</span><span class="ref-title">Genius Makers</span></div><div class="ref-meta">Cade Metz · 2021</div><p class="ref-desc">NYT 记者写的深度学习革命口述史。Hinton/LeCun/Bengio/Sutskever 群像。</p></div></li><li class="ref-item" id="ref-B15"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B15</span><span class="ref-title">The Coming Wave</span></div><div class="ref-meta">Mustafa Suleyman · 2023</div><p class="ref-desc">DeepMind 联合创始人对 AI + 合成生物的合击预言。</p></div></li><li class="ref-item" id="ref-B16"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B16</span><span class="ref-title">Co-Intelligence: Living and Working with AI</span></div><div class="ref-meta">Ethan Mollick · 2024</div><p class="ref-desc">Wharton 教授写&quot;如何用 LLM 思考&quot;。流畅好读，给&quot;如何与机器合作&quot;角度。</p></div></li><li class="ref-item" id="ref-B17"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B17</span><span class="ref-title">Why Machines Learn: The Elegant Math Behind Modern AI</span></div><div class="ref-meta">Anil Ananthaswamy · 2024</div><p class="ref-desc">数学优雅，叙事清晰。从感知机到 Transformer 的另一条线。</p></div></li><li class="ref-item" id="ref-B18"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B18</span><span class="ref-title">The Atomic Human</span></div><div class="ref-meta">Neil D. Lawrence · 2024</div><p class="ref-desc">剑桥 ML 教授写&quot;人之为人在哪里&quot;——给&quot;人 vs 机器&quot;提供哲学坐标。</p></div></li><li class="ref-item" id="ref-B19"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B19</span><span class="ref-title">AI Snake Oil</span></div><div class="ref-meta">Narayanan &amp; Kapoor · 2024</div><p class="ref-desc">见 A20。配套书。Princeton Univ. Press。</p></div></li><li class="ref-item" id="ref-B20"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B20</span><span class="ref-title">Deep Utopia: Life and Meaning in a Solved World</span></div><div class="ref-meta">Nick Bostrom · 2024</div><p class="ref-desc">Bostrom 写&quot;假如 AGI 真的来了，人类怎么办&quot;。课程 L35 (Predictions) 的对照阅读。</p></div></li><li class="ref-item" id="ref-B21"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B21</span><span class="ref-title">The Singularity Is Nearer</span></div><div class="ref-meta">Ray Kurzweil · 2024</div><p class="ref-desc">Kurzweil 1999 《奇点临近》之续。给&quot;乐观派&quot;视角。批评者甚多，但需要听到这个观点。</p></div></li><li class="ref-item" id="ref-B22"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B22</span><span class="ref-title">Nexus: A Brief History of Information Networks from the Stone Age to AI</span></div><div class="ref-meta">Yuval Noah Harari · 2024</div><p class="ref-desc">Harari 转向 AI 主题。&quot;人类大脑也只是信息网络&quot;——本讲核心隐喻的人文版本。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="现代可视化与交互式演示-可用于讲义">12. 现代可视化与交互式演示（可用于讲义）</h2><ol class="ref-list"><li class="ref-item" id="ref-V11"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V11</span><a class="ref-title" href="https://bbycroft.net/llm" target="_blank" rel="noopener">LLM Visualization (3D walk-through)</a></div><div class="ref-meta">Brendan Bycroft</div><p class="ref-desc">浏览器内 3D nano-GPT 推理可视化。&quot;机器在想什么&quot;演示首选。</p></div></li><li class="ref-item" id="ref-V12"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V12</span><a class="ref-title" href="https://poloclub.github.io/transformer-explainer/" target="_blank" rel="noopener">Transformer Explainer</a></div><div class="ref-meta">Georgia Tech / Polo Chau</div><p class="ref-desc">浏览器交互式 Transformer 可视化。配 GPT-2 实时跑。</p></div></li><li class="ref-item" id="ref-V13"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V13</span><a class="ref-title" href="https://poloclub.github.io/cnn-explainer/" target="_blank" rel="noopener">CNN Explainer</a></div><div class="ref-meta">Polo Chau group</div><p class="ref-desc">演示视觉系统层级——和&quot;人类视觉是有偏的&quot;对比。</p></div></li><li class="ref-item" id="ref-V14"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V14</span><a class="ref-title" href="https://busterbenson.com/piles/cognitive-biases/" target="_blank" rel="noopener">Cognitive Bias Codex (interactive)</a></div><div class="ref-meta">Buster Benson</div><p class="ref-desc">完整 188 个偏误的层级地图。</p></div></li><li class="ref-item" id="ref-V15"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V15</span><a class="ref-title" href="https://michaelbach.de/ot/" target="_blank" rel="noopener">Optical Illusions Database</a></div><div class="ref-meta">Michael Bach</div><p class="ref-desc">视觉错觉百科。开场暖场首选。</p></div></li><li class="ref-item" id="ref-V16"><span class="ref-stars" data-stars="1" aria-label="评级 1 星">●<span class="ref-stars-empty">○○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V16</span><span class="ref-title">The Visual Cortex Hierarchy (interactive)</span></div><p class="ref-desc">给&quot;人脑也是分层特征提取器&quot;做铺垫。</p></div></li><li class="ref-item" id="ref-V17"><span class="ref-stars" data-stars="2" aria-label="评级 2 星">●●<span class="ref-stars-empty">○○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V17</span><a class="ref-title" href="https://playground.tensorflow.org/" target="_blank" rel="noopener">Neural Network Playground</a></div><div class="ref-meta">TensorFlow</div><p class="ref-desc">&quot;你来训一个神经网络&quot;——比理论解释更有冲击力。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="播客与长访谈-课前推荐收听">13. 播客与长访谈（课前推荐收听）</h2><ol class="ref-list"><li class="ref-item" id="ref-PC1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC1</span><a class="ref-title" href="https://lexfridman.com/sam-altman-2/" target="_blank" rel="noopener">#367 — Sam Altman</a></div><div class="ref-meta">Lex Fridman · 2024 · 1.5h</div><p class="ref-desc">&quot;AGI 时间表&quot; + &quot;AI 是什么&quot;</p></div></li><li class="ref-item" id="ref-PC2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC2</span><a class="ref-title" href="https://lexfridman.com/andrej-karpathy/" target="_blank" rel="noopener">#386 — Andrej Karpathy</a></div><div class="ref-meta">Lex Fridman · 2024 · 3.5h</div><p class="ref-desc">从 Tesla 到 LLM</p></div></li><li class="ref-item" id="ref-PC3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC3</span><a class="ref-title" href="https://lexfridman.com/yann-lecun-3/" target="_blank" rel="noopener">Yann LeCun: Limits of LLMs, AGI &amp; the Future of AI</a></div><div class="ref-meta">Lex Fridman · 2024 · 3h</div><p class="ref-desc">LLM 不能推理，本讲反方</p></div></li><li class="ref-item" id="ref-PC4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC4</span><span class="ref-title">Geoffrey Hinton — Why he left Google + AI risks</span></div><div class="ref-meta">Lex Fridman / Hinton interviews · 2024</div><p class="ref-desc">第一手&quot;我担心机器太聪明&quot;</p></div></li><li class="ref-item" id="ref-PC5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC5</span><span class="ref-title">Daniel Kahneman — On Noise, Bias, and the End of an Era</span></div><div class="ref-meta">2024</div><p class="ref-desc">Kahneman 2024 年逝世前的最后访谈集合</p></div></li><li class="ref-item" id="ref-PC6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC6</span><a class="ref-title" href="https://www.preposterousuniverse.com/podcast/" target="_blank" rel="noopener">Andy Clark — The Predictive Mind</a></div><div class="ref-meta">Mindscape (Sean Carroll) · 2023 · 1h</div><p class="ref-desc">预测处理理论：人脑就是预测机器。本讲科学基础。</p></div></li><li class="ref-item" id="ref-PC7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC7</span><span class="ref-title">Karl Friston on Active Inference</span></div><div class="ref-meta">2023-24</div><p class="ref-desc">&quot;自由能原理&quot;——人脑/AI 统一框架的最激进候选。</p></div></li><li class="ref-item" id="ref-PC8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC8</span><a class="ref-title" href="https://www.dwarkesh.com/p/sholto-trenton" target="_blank" rel="noopener">Trenton Bricken &amp; Sholto Douglas (Anthropic Mechanistic Interpretability)</a></div><div class="ref-meta">Dwarkesh Patel · 2024 · 4h</div><p class="ref-desc">直接打开 Claude 大脑看里面有什么</p></div></li><li class="ref-item" id="ref-PC9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC9</span><a class="ref-title" href="https://www.cognitiverevolution.ai/" target="_blank" rel="noopener">Cognitive Revolution Episodes on Bias / Hallucination</a></div><div class="ref-meta">Erik Torenberg, Nathan Labenz · 2023-26 · weekly</div><p class="ref-desc">多集涉及 LLM 的&quot;心理学&quot;</p></div></li><li class="ref-item" id="ref-PC10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">PC10</span><a class="ref-title" href="https://thegradientpub.substack.com/" target="_blank" rel="noopener">The Gradient Podcast</a></div><div class="ref-meta">Daniel Bashir · 2023-26 · weekly</div><p class="ref-desc">学者深度访谈，包括 Marcus, Mitchell, Bender 等批评派</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="批评与怀疑的声音-重要反方阅读">14. 批评与怀疑的声音（重要反方阅读）</h2><p class="ref-prose">&gt; 本讲必须给学生听到反方：&quot;机器认知 ≠ 人类认知&quot;的论证版本。</p><ol class="ref-list"><li class="ref-item" id="ref-K1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">K1</span><span class="ref-title">Rebooting AI: Building Artificial Intelligence We Can Trust</span></div><div class="ref-meta">Gary Marcus &amp; Ernest Davis · 2019</div><p class="ref-desc">&quot;深度学习走错了路。需要 hybrid neural-symbolic AI.&quot;</p></div></li><li class="ref-item" id="ref-K2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">K2</span><a class="ref-title" href="https://dl.acm.org/doi/10.1145/3442188.3445922" target="_blank" rel="noopener"><strong>Stochastic Parrots paper</strong> (On the Dangers of Stochastic Parrots)</a></div><div class="ref-meta">Bender, Gebru, McMillan-Major, Shmitchell · 2021</div><p class="ref-desc">&quot;LLM 只是模式匹配，不是理解。&quot;——史上最被引用的 LLM 批评文。</p></div></li><li class="ref-item" id="ref-K3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">K3</span><a class="ref-title" href="https://aclanthology.org/2020.acl-main.463/" target="_blank" rel="noopener">Climbing towards NLU: On Meaning, Form, and Understanding in the Age of Data</a></div><div class="ref-meta">Bender &amp; Koller · 2020</div><p class="ref-desc">&quot;形式 ≠ 意义&quot;——学术化版本的 Stochastic Parrots。</p></div></li><li class="ref-item" id="ref-K4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">K4</span><a class="ref-title" href="https://arxiv.org/abs/1801.00631" target="_blank" rel="noopener">Deep Learning: A Critical Appraisal</a></div><div class="ref-meta">Gary Marcus · 2018</div><p class="ref-desc">10 个深度学习的根本局限。</p></div></li><li class="ref-item" id="ref-K5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">K5</span><a class="ref-title" href="https://www.pnas.org/doi/10.1073/pnas.2215907120" target="_blank" rel="noopener">The Debate Over Understanding in AI&#39;s Large Language Models</a></div><div class="ref-meta">Melanie Mitchell · 2023</div><p class="ref-desc">Santa Fe Institute 教授综述：&quot;理解&quot;在 AI 语境下到底意味着什么——双方论证。</p></div></li><li class="ref-item" id="ref-K6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">K6</span><span class="ref-title">AI&#39;s Spooky Failure Modes</span></div><div class="ref-meta">2024-25</div><p class="ref-desc">LLM 在&quot;边界外&quot;做出的离奇错误集锦。</p></div></li><li class="ref-item" id="ref-K7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">K7</span><a class="ref-title" href="https://arxiv.org/abs/2506.06941" target="_blank" rel="noopener"><strong>Apple&#39;s &quot;The Illusion of Thinking&quot;</strong> (reasoning models)</a></div><div class="ref-meta">Apple ML team · 2025</div><p class="ref-desc">2025 年 Apple 论文：reasoning models 在难度阈值之外完全崩溃。震动业界，本讲必提。</p></div></li></ol></section>',19)])])}const h=a(t,[["render",l]]);export{v as __pageData,h as default};
